        ['q' => 'வழங்குநர் சரிபார்ப்பு எப்படி நடக்கிறது?', 'a' => 'வழங்குநர் தொழில் விவரங்கள், அரசு அடையாள எண், முகவரிச் சான்று, மேலும் அவர்களின் பிரிவுக்குத் தேவையான பதிவு (எ.கா. கட்டடக் கலைஞர்களுக்குக் கட்டடக் கலைக் குழுமப் பதிவு) ஆகியவற்றைச் சமர்ப்பிக்கிறார். நிர்வாகி ஒவ்வொன்றையும் நேரடியாகச் சரிபார்த்து முடிவைப் பதிவு செய்கிறார். தேவையான அனைத்துச் சரிபார்ப்புகளும் முடிந்த பிறகே சுயவிவரம் வெளியிடப்படும்.'],
