        ['q' => 'ஒரு பிரிவில் “விரைவில்” என்று உள்ளது. நான் என்ன செய்யலாம்?', 'a' => 'அந்தப் பக்கத்திலிருந்து விசாரணை அனுப்புங்கள். ஒவ்வொரு விசாரணையையும் குழு படித்து, பொருத்தமான வழங்குநரைக் கண்டறிய முயலும்.'],
        ['q' => 'ஒரே கணக்கைப் பயனராகவும் வழங்குநராகவும் பயன்படுத்தலாமா?', 'a' => 'இல்லை. பதிவு செய்யும்போது பங்கு ஒருமுறை மட்டுமே தேர்ந்தெடுக்கப்படும். தொழிலைப் பட்டியலிட, உங்கள் தொழில் மொபைல் எண்ணுடன் தனிக் கணக்கைப் பதிவு செய்யுங்கள்.'],
        ['q' => 'என் மொபைல் எண்ணும் மின்னஞ்சலும் ஏன் பகுதியாக மறைக்கப்பட்டுள்ளன?', 'a' => 'பொதுத் திரையில் வெளிப்படாமல் இருக்க, சுருக்கங்களில் தொடர்பு மற்றும் அடையாள விவரங்கள் மறைத்தே காட்டப்படுகின்றன.'],
        ['q' => 'இலவச, புரோ, பிரீமியம் பட்டியல்கள் என்றால் என்ன?', 'a' => 'வாடிக்கையாளர்கள் எவ்வளவு நிறுவனத் தகவலைப் பார்க்கிறார்கள் என்பதை அவை தீர்மானிக்கின்றன. இலவசம் நிறுவனப் பெயரையும் 300 எழுத்துகள் வரையிலான விளக்கத்தையும் காட்டும். புரோ நீண்ட விளக்கம் (1,000 எழுத்துகள் வரை), தொழில் முகவரி, இணையதளம், தொழில் தொலைபேசி, WhatsApp பொத்தான் ஆகியவற்றைச் சேர்க்கும். பிரீமியம் தொழில் மின்னஞ்சல், நிறுவனப் படங்கள், வழங்கும் சேவைகள், படங்கள் வீடியோக்களுடன் முடித்த பணிகள் ஆகியவற்றைச் சேர்க்கும். வழங்குநர்கள் தங்கள் முகப்புப் பலகையில் திட்டத்தைத் தேர்ந்தெடுத்து அதன் விவரங்களைத் தயாரிக்கலாம்; விலை, கட்டணம், திட்டச் செயல்படுத்தல் ஆகியவை இன்னும் இயக்கப்படவில்லை, எனவே தேர்வு இப்போது பட்டியலை மாற்றாது.'],
